"""
    calculate coo of points in a resized img
    in pts pair of coo (x,y)
    """
def resize_pts(
    pts: Any, ow: Any, oh: Any, nw: Any, nh: Any, pos_w: Any, pos_h: Any
) -> object {
    new_pts = [];
    for p in pts {
        ox = p[0];
        oy = p[1];
        newx = ((ox / float(ow)) * nw) + pos_w;
        newy = ((oy / float(oh)) * nh) + pos_h;
        new_pts.append((newx, newy));
    }
    return new_pts;
}

"""
    convert byte to GB
    :param byte_number: byte number
    :return: GB
    """
def byte_to_gb(byte_number: Any) -> object {
    return (byte_number / (1024 ** 3));
}

"""Returns the "average" of the normal distributions from NormalParameters.
NormalParameters: a list of length 2 lists, whose entries are the mean and SD of each normal distribution."""
def NormalsAverage(NormalParameters: Any) -> object {
    return [
        (sum([Parameter[0] for Parameter in NormalParameters]) / len(NormalParameters)),
        (
            (
                sum([(Parameter[1] ** 2) for Parameter in NormalParameters])
                / (len(NormalParameters) ** 2)
            )
            ** (1 / 2)
        )
    ];
}

